{
  "description": "The creature is a quadrupedal, pangolin-like animal shown in right-facing profile against a plain light background, standing on all four limbs with its body arched and its long tail extended horizontally behind it. Most of its dorsal and lateral surfaces, the top of its elongated snout, its limbs, and its tail are covered in overlapping, dark brown to grayish, keeled scales with lighter edges. Large, irregular patches of pale pink, wrinkled, fleshy skin are exposed where scales are missing on the mid-back, the mid-flank, and the lower rear flank. The head is elongated into a tapered snout with a dark nostril at the tip and fine whiskers, a small dark round eye on the side, and a small rounded ear behind the eye. The limbs are short and thick, ending in broad feet with long, curved, dark claws, and the tail is thick at the base and tapers to a point.",
  "parts": [
    {
      "part": "head",
      "looks_like": "elongated and tapered to a blunt snout with a dark nostril at the tip, fine whiskers at the muzzle, a small dark round eye on the side, and wrinkled gray-brown skin on the face; the crown and bridge of the snout are covered in small overlapping scales",
      "where": "at the front right end of the body, extending forward from the scaled neck"
    },
    {
      "part": "ears",
      "looks_like": "small, rounded, fleshy ear with a visible inner ridge and fine hairs around the margin, pale gray-brown",
      "where": "on the side of the head just behind and slightly above the eye, at the edge of the scaled cap"
    },
    {
      "part": "eyes",
      "looks_like": "small, round, glossy black eye with a faint pale ring and fine wrinkles around it",
      "where": "on the side of the head, forward of the ear and below the scaled crown"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, muscular legs with pale, wrinkled skin on the lower portions and overlapping dark scales on the upper and outer portions; the forelimbs are positioned under the chest and the hindlimbs under the rear",
      "where": "two forelimbs extending down from the chest, two hindlimbs extending down from the rear underside, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad, fleshy feet with thick pads and three to four long, thick, curved, dark brown-black claws per foot; the skin is pale with dark speckling and dirt around the claws",
      "where": "at the distal ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick at the base and tapering to a blunt point, covered dorsally and laterally in overlapping dark scales with visible segmentation underneath",
      "where": "extending horizontally to the rear from behind the hind legs, lying just above the ground"
    },
    {
      "part": "scales",
      "looks_like": "overlapping, rounded-triangular, keeled keratinous scales, dark brown to gray with lighter tan edges and fine striations, larger on the back and sides and smaller on the head, limbs, and tail",
      "where": "covering the dorsal surface, sides, top of head and snout, outer limbs, and tail, except where interrupted by pink skin patches"
    },
    {
      "part": "markings",
      "looks_like": "large, irregular, pale pink, fleshy, wrinkled patches of exposed skin with soft folds, lacking scales",
      "where": "one large patch on the mid-dorsal back, one on the mid-lateral flank above the forelimb, and a smaller lobed patch on the lower rear flank above the hind leg"
    }
  ],
  "attached_objects": [],
  "animals": ["pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
